<div class="mb-6 flex items-end justify-between"><div><p class="text-sm font-medium text-blue-600">Consulta histórica</p><h1 class="text-2xl font-bold">Historial por trabajador</h1><p class="text-sm text-slate-500">Planillas, pagos acumulados y saldos entre períodos.</p></div><a href="index.php?url=planilla" class="rounded-xl border bg-white px-4 py-2 text-sm font-semibold">Volver</a></div>
<form method="get" class="mb-5 rounded-2xl border bg-white p-4"><input type="hidden" name="url" value="planilla_historial"><label class="form-label">Trabajador<select name="persona" onchange="this.form.submit()" class="form-input"><option value="0">Todos</option><?php foreach($trabajadores as $t):?><option value="<?= $t['id_persona'] ?>" <?= $persona==$t['id_persona']?'selected':'' ?>><?= htmlspecialchars($t['trabajador'].' · '.($t['codigo_trabajador']?:'Sin código')) ?></option><?php endforeach;?></select></label></form>
<section class="mb-5 grid gap-4 sm:grid-cols-3"><?php foreach([['Total neto','neto'],['Pagado','pagado'],['Saldo','saldo']] as $t):?><article class="rounded-2xl border bg-white p-5"><p class="text-xs uppercase text-slate-500"><?= $t[0] ?></p><p class="text-2xl font-bold">S/ <?= number_format($totales[$t[1]],2) ?></p></article><?php endforeach;?></section>
<section class="overflow-hidden rounded-2xl border bg-white"><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-4">Trabajador</th><th class="p-4">Período</th><th class="p-4">Neto</th><th class="p-4">Pagado</th><th class="p-4">Saldo</th><th class="p-4">Estado</th><th class="no-sort p-4">Acciones</th></tr></thead><tbody><?php foreach($historial as $h):?><tr class="border-t"><td class="p-4 font-medium"><?= htmlspecialchars($h['trabajador']) ?></td><td class="p-4"><?= htmlspecialchars($h['periodo']) ?><small class="block text-slate-500"><?= $h['fecha_inicio'] ?> a <?= $h['fecha_fin'] ?></small></td><td class="p-4">S/ <?= number_format($h['monto_pagar'],2) ?></td><td class="p-4 text-emerald-700">S/ <?= number_format($h['monto_pagado'],2) ?></td><td class="p-4 text-rose-700">S/ <?= number_format($h['saldo_pendiente'],2) ?></td><td class="p-4"><?= htmlspecialchars($h['estado']) ?></td><td class="p-4"><?php if(in_array($h['periodo_estado'],['CERRADO','PAGADO'],true)&&tienePermiso('planilla.cerrar')):?><a href="index.php?url=planilla_pagos&id=<?= $h['id_periodo_pago'] ?>" class="rounded-lg bg-blue-100 px-3 py-2 text-xs font-semibold text-blue-700">Ver pagos y constancias</a><?php else:?><a href="index.php?url=planilla_revision&id=<?= $h['id_periodo_pago'] ?>" class="text-xs font-semibold text-emerald-700">Ver detalle</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
